import{_ as a,o as e,c as n,a2 as s}from"./chunks/framework.XXezeKOl.js";const u=JSON.parse('{"title":"论文精读","description":"精选 8 篇影响 Agent 开发方式的论文，讲清每篇解决了什么问题、方法是什么、对今天的工程实践有什么启发。","frontmatter":{"title":"论文精读","description":"精选 8 篇影响 Agent 开发方式的论文，讲清每篇解决了什么问题、方法是什么、对今天的工程实践有什么启发。"},"headers":[],"relativePath":"papers/index.md","filePath":"papers/index.md","lastUpdated":null}'),r={name:"papers/index.md"};function p(d,t,o,l,i,h){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="论文精读" tabindex="-1">论文精读 <a class="header-anchor" href="#论文精读" aria-label="Permalink to &quot;论文精读&quot;">​</a></h1><p>Agent 领域的很多工程实践，比如思维链提示、ReAct 循环、自我反思、检索增强，最早都来自论文。读原始论文能帮你理解这些方法&quot;为什么有效、在什么条件下有效&quot;，遇到框架没覆盖的问题时，你也知道该往哪个方向想。</p><p>这里选的 8 篇不追求最新，而是追求影响深远：它们提出的思路已经成为今天 Agent 框架和产品的默认设计。</p><h2 id="论文列表" tabindex="-1">论文列表 <a class="header-anchor" href="#论文列表" aria-label="Permalink to &quot;论文列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>论文</th><th>年份</th><th>一句话收获</th></tr></thead><tbody><tr><td><a href="/papers/rag">RAG 原始论文</a></td><td>2020</td><td>把&quot;检索外部知识&quot;和&quot;生成答案&quot;结合起来，让模型的知识可以更新、可以溯源</td></tr><tr><td><a href="/papers/chain-of-thought">Chain-of-Thought</a></td><td>2022</td><td>让模型先写出推理步骤再给答案，能明显提升复杂推理任务的表现</td></tr><tr><td><a href="/papers/react">ReAct</a></td><td>2022</td><td>推理与行动交替进行，是今天大多数 Agent 循环的原型</td></tr><tr><td><a href="/papers/toolformer">Toolformer</a></td><td>2023</td><td>模型可以通过自监督的方式学会何时调用工具、传什么参数</td></tr><tr><td><a href="/papers/reflexion">Reflexion</a></td><td>2023</td><td>用语言形式的自我反思代替参数更新，让 Agent 在多次尝试中改进</td></tr><tr><td><a href="/papers/generative-agents">Generative Agents</a></td><td>2023</td><td>记忆流、反思和规划三件套，奠定了 Agent 记忆系统的基本架构</td></tr><tr><td><a href="/papers/tree-of-thoughts">Tree of Thoughts</a></td><td>2023</td><td>把推理过程变成树搜索，允许探索多条路径并回溯</td></tr><tr><td><a href="/papers/swe-agent">SWE-agent</a></td><td>2024</td><td>为 Agent 专门设计的交互界面（ACI）对效果的影响很大</td></tr></tbody></table><p>建议阅读顺序：Chain-of-Thought → ReAct → Reflexion → Tree of Thoughts → Toolformer → RAG → Generative Agents → SWE-agent。前四篇是&quot;推理与行动&quot;一条线，后四篇分别对应工具、知识、记忆和真实环境中的 Agent。</p><h2 id="怎么读论文" tabindex="-1">怎么读论文 <a class="header-anchor" href="#怎么读论文" aria-label="Permalink to &quot;怎么读论文&quot;">​</a></h2><p>不需要逐字读完。工程师读论文的目标是拿到可以用的思路，推荐三遍读法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一遍（10 分钟）           第二遍（30-60 分钟）          第三遍（按需）</span></span>
<span class="line"><span>┌──────────────────┐       ┌──────────────────────┐      ┌──────────────────────┐</span></span>
<span class="line"><span>│ 标题、摘要、图表   │  ──▶  │ 方法部分、提示词示例   │ ──▶  │ 复现：用今天的模型      │</span></span>
<span class="line"><span>│ 结论              │       │ 实验设置、消融实验     │      │ 和 API 写一个最小版本   │</span></span>
<span class="line"><span>│ 回答：它解决什么？ │       │ 回答：为什么有效？     │      │ 回答：在我的场景成立吗？│</span></span>
<span class="line"><span>└──────────────────┘       └──────────────────────┘      └──────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>读的时候带着几个问题：</p><ul><li><strong>问题是什么？</strong> 之前的方法哪里不行？</li><li><strong>核心思想能用一句话说清吗？</strong> 说不清说明还没读懂。</li><li><strong>实验比较的是什么？</strong> 基线是谁，提升来自哪里，消融实验去掉了什么。</li><li><strong>前提条件是什么？</strong> 很多论文结论依赖当时的模型规模或特定任务，换到今天的模型上未必成立。</li><li><strong>对我有什么用？</strong> 能不能变成一段提示词、一个循环结构或一条工程规范。</li></ul><div class="warning custom-block"><p class="custom-block-title">注意时效性</p><p>这些论文发表时使用的模型，能力和今天的模型差距很大。论文里&quot;某方法提升了多少&quot;的结论，在今天的模型上幅度可能完全不同，有些技巧甚至已经被模型内化（比如推理模型自带思维链）。学习重点是思想，而不是具体数字。</p></div><h2 id="每篇精读的结构" tabindex="-1">每篇精读的结构 <a class="header-anchor" href="#每篇精读的结构" aria-label="Permalink to &quot;每篇精读的结构&quot;">​</a></h2><p>每篇文章都按同样的结构组织：论文信息、一句话总结、要解决的问题、核心方法、关键实验结论、对 Agent 开发的启发、局限性、相关文章。如果时间有限，优先看&quot;对 Agent 开发的启发&quot;一节。</p><p>论文原文都在 <a href="https://arxiv.org/" target="_blank" rel="noreferrer">arXiv</a> 上免费获取。</p>`,15)])])}const g=a(r,[["render",p]]);export{u as __pageData,g as default};
